<?php
session_start();require_once '../shared/config.php';require_once '../shared/security.php';
o2oCsrfToken();if(!isset($_SESSION['admin_id'])){header('Location: login.php');exit;}$db=getDB();
$to=trim($_GET['to']??date('Y-m-d'));$from=trim($_GET['from']??date('Y-m-d',strtotime('-29 days')));
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-d',strtotime('-29 days'));
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');
$summary=['rental'=>0.0,'purchase'=>0.0,'rental_orders'=>0,'purchase_orders'=>0,'customers'=>0,'vendors'=>0];
$st=$db->prepare("SELECT COALESCE(SUM(total_rent+COALESCE(late_charges,0)),0),COUNT(*) FROM orders WHERE status='completed' AND DATE(created_at) BETWEEN ? AND ?");$st->execute([$from,$to]);[$summary['rental'],$summary['rental_orders']]=$st->fetch(PDO::FETCH_NUM);
$st=$db->prepare("SELECT COALESCE(SUM(total_amount),0),COUNT(*) FROM purchase_orders WHERE order_status='delivered' AND DATE(created_at) BETWEEN ? AND ?");$st->execute([$from,$to]);[$summary['purchase'],$summary['purchase_orders']]=$st->fetch(PDO::FETCH_NUM);
$st=$db->prepare("SELECT COUNT(*) FROM customers WHERE DATE(created_at) BETWEEN ? AND ?");$st->execute([$from,$to]);$summary['customers']=(int)$st->fetchColumn();
$st=$db->prepare("SELECT COUNT(*) FROM vendors WHERE DATE(created_at) BETWEEN ? AND ?");$st->execute([$from,$to]);$summary['vendors']=(int)$st->fetchColumn();
$st=$db->prepare("SELECT DATE(created_at) d,COUNT(*) orders,COALESCE(SUM(total_rent+COALESCE(late_charges,0)),0) revenue FROM orders WHERE status='completed' AND DATE(created_at) BETWEEN ? AND ? GROUP BY DATE(created_at) ORDER BY d DESC");$st->execute([$from,$to]);$rentDays=$st->fetchAll();
$st=$db->prepare("SELECT DATE(created_at) d,COUNT(*) orders,COALESCE(SUM(total_amount),0) revenue FROM purchase_orders WHERE order_status='delivered' AND DATE(created_at) BETWEEN ? AND ? GROUP BY DATE(created_at) ORDER BY d DESC");$st->execute([$from,$to]);$buyDays=$st->fetchAll();
$st=$db->prepare("SELECT i.category,COUNT(*) units,COALESCE(SUM(poi.total_price),0) revenue FROM purchase_order_items poi JOIN purchase_orders po ON po.id=poi.order_id JOIN items i ON i.id=poi.item_id WHERE po.order_status='delivered' AND DATE(po.created_at) BETWEEN ? AND ? GROUP BY i.category ORDER BY revenue DESC LIMIT 8");$st->execute([$from,$to]);$categories=$st->fetchAll();
$total=(float)$summary['rental']+(float)$summary['purchase'];
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Analytics – O2O Tradition</title><style>body{font-family:Arial;background:#FAF6EE;color:#3D2B0F;margin:0}.nav{background:#1A1108;color:#C9A84C;padding:20px 30px;display:flex;justify-content:space-between}.nav a{color:#E8CC82;text-decoration:none;margin-left:15px}.main{max-width:1150px;margin:auto;padding:30px}.hero,.card,.stat{background:#fff;border:1px solid #E8E0D0;padding:20px;margin-bottom:18px}.hero{background:#21170B;color:#fff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:15px}.stat b{font-size:27px;color:#8B1A1A;display:block;margin-top:7px}.filters{display:flex;gap:10px;flex-wrap:wrap}.input,.btn{padding:10px;border:1px solid #ddd}.btn{background:#1A1108;color:#C9A84C;border:0}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{padding:9px;border-bottom:1px solid #eee;text-align:left}.small{color:#777;font-size:12px}</style></head><body><div class="nav"><b>O2O Tradition · Admin</b><div><a href="dashboard.php">Dashboard</a><a href="analytics.php">Analytics</a><a href="audit.php">Audit</a><a href="logout.php">Logout</a></div></div><main class="main"><section class="hero"><h1>Platform Analytics</h1><p>Completed rental and delivered purchase activity for the selected period. Figures are operational marketplace totals, not profit.</p></section><section class="card"><form class="filters"><label>From <input class="input" type="date" name="from" value="<?=htmlspecialchars($from)?>"></label><label>To <input class="input" type="date" name="to" value="<?=htmlspecialchars($to)?>"></label><button class="btn">Apply</button></form></section><div class="grid"><div class="stat">Marketplace Revenue<b>₹<?=number_format($total,2)?></b></div><div class="stat">Rental Revenue<b>₹<?=number_format((float)$summary['rental'],2)?></b><span class="small"><?=$summary['rental_orders']?> completed rentals</span></div><div class="stat">Purchase Revenue<b>₹<?=number_format((float)$summary['purchase'],2)?></b><span class="small"><?=$summary['purchase_orders']?> delivered purchases</span></div><div class="stat">New Customers<b><?=$summary['customers']?></b></div><div class="stat">New Vendors<b><?=$summary['vendors']?></b></div></div><section class="card"><h2>Daily activity</h2><table class="table"><tr><th>Date</th><th>Rental orders</th><th>Rental revenue</th><th>Purchase orders</th><th>Purchase revenue</th></tr><?php $days=[];foreach($rentDays as $r)$days[$r['d']]['r']=$r;foreach($buyDays as $r)$days[$r['d']]['b']=$r;krsort($days);foreach($days as $d=>$x):?><tr><td><?=htmlspecialchars($d)?></td><td><?=isset($x['r'])?(int)$x['r']['orders']:0?></td><td>₹<?=number_format((float)($x['r']['revenue']??0),2)?></td><td><?=isset($x['b'])?(int)$x['b']['orders']:0?></td><td>₹<?=number_format((float)($x['b']['revenue']??0),2)?></td></tr><?php endforeach;if(!$days):?><tr><td colspan="5">No completed activity in this period.</td></tr><?php endif;?></table></section><section class="card"><h2>Top purchase categories</h2><table class="table"><tr><th>Category</th><th>Units</th><th>Revenue</th></tr><?php foreach($categories as $r):?><tr><td><?=htmlspecialchars($r['category']??'Uncategorised')?></td><td><?=$r['units']?></td><td>₹<?=number_format((float)$r['revenue'],2)?></td></tr><?php endforeach;if(!$categories):?><tr><td colspan="3">No delivered purchases in this period.</td></tr><?php endif;?></table></section></main></body></html>